import { nanoid } from "nanoid";
import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  books: [
    {
      id: nanoid(),
      name: "Хроніки Амбера",
      author: "Роджер Желязни",
      year:'1970-1991',
      publishYear: "2020",
      genre: "фентезі",
      publisher: "Богдан",
      cover: "https://bohdan-books.com/upload/resize_cache/iblock/671/381_562_2/671ce6e978d3bf116e60285cad140c73.jpg",
      pages: "720",
      color: "#102f20",
      textColor: "#d8e2d6",
      read: true,
      series: "",
      volumes: "",
      part:'',
      rating: "",
      description: "",
      language:'',
    },
    {
      id: nanoid(),
      name: "Хроніки Амбера",
      author: "Роджер Бл",
      year:'',
      publishYear: "",
      genre: "фентезі, дарк",
      publisher: "",
      cover: "https://vivat.com.ua/resize_960x1371x95/storage/1.d/files/c/9/c96886d4_mokap-zi-zrizom-obranka-3406.webp",
      pages: "864",
      color: "#102f20",
      textColor: "#d8e2d6",
      read: true,
      series: "",
      volumes: "",
      part:'',
      rating: "",
      description: "",
      language:'',
    },
  ]
  }
const bookSlice = createSlice({
  name: "books",
  initialState: initialState.books,
  reducers: {
    addBook: {
      reducer(state, action) {
        state.push(action.payload);
      },
      prepare(name, author) {
        return {
          payload: {
            name,
            id: nanoid(),
            author: author,
          },
        };
      },
    },
    deleteBook(state, action) {
      return state.filter((book) => book.id !== action.payload);
    },
  },
});

export const { addBook, deleteBook } = bookSlice.actions;
export const booksReducer = bookSlice.reducer;
